// Generated at build/test time from `<lang>.json` by `i18n-fallback-plugin.ts`: `<lang>.<slice>.pack.json` (a slice's own keys) and
// `<lang>.<slice>.delta.pack.json` (the `ua` keys of that slice the language lacks). See `packs.ts`.
declare module '*.pack.json' {
  const dictionary: Record<string, string>
  export default dictionary
}
